{
  "name": "FiscalNews Automator México",
  "description": "Automatización inteligente para buscar, resumir y compartir noticias fiscales y laborales de México (SAT, IMSS, Infonavit, UMA) vía Google Chat.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface NewsItem {
  id: string;
  topic: string;
  title: string;
  summary: string;
  date: string;
  links: { title: string; uri: string }[];
  fullText: string;
}

export interface AppSettings {
  googleChatWebhook: string;
  selectedTopics: string[];
}

export enum Topic {
  SAT = 'SAT',
  IMSS = 'IMSS',
  INFONAVIT = 'Infonavit',
  UMA = 'UMA',
  IDSE = 'IDSE',
  CFDI = 'CFDI',
  SUA = 'SUA'
}

export const TOPICS_LIST = Object.values(Topic);

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Topic, NewsItem } from "../types";

const API_KEY = process.env.API_KEY || '';

export const fetchFiscalNews = async (topics: string[]): Promise<NewsItem[]> => {
  if (!API_KEY) {
    throw new Error("API Key no configurada.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = 'gemini-3-flash-preview';

  const topicsStr = topics.join(', ');
  const prompt = `
    Busca las noticias más recientes y relevantes en México sobre los siguientes temas: ${topicsStr}.

    Fuentes Prioritarias:
    - SAT (sat.gob.mx)
    - IMSS (imss.gob.mx)
    - Infonavit (infonavit.org.mx)
    - CONASAMI (conasami.gob.mx)
    - Medios: El Universal, Milenio, Animal Político.

    Para cada tema, proporciona:
    1. Un título conciso.
    2. Un resumen ejecutivo de 2-3 párrafos explicando los cambios, fechas clave o impactos para patrones/empleados.
    3. Asegúrate de incluir los links de las fuentes oficiales o medios reconocidos.

    Responde en formato estructurado para que pueda ser procesado fácilmente.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "No se encontró información.";
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract links from grounding chunks
    const links = chunks
      .filter(chunk => chunk.web)
      .map(chunk => ({
        title: chunk.web?.title || 'Fuente externa',
        uri: chunk.web?.uri || ''
      }));

    // For simplicity in this demo, we'll treat the whole response as one item per topic or a consolidated summary
    // In a production app, we'd use responseSchema to get a clean array.
    // Here we'll map the text to a news item structure.

    return [{
      id: crypto.randomUUID(),
      topic: topics.length > 1 ? "Resumen Fiscal General" : topics[0],
      title: `Actualización Fiscal y Laboral: ${topicsStr}`,
      summary: text.substring(0, 500) + "...",
      fullText: text,
      date: new Date().toLocaleDateString('es-MX'),
      links: links.slice(0, 10) // Limit to top 10 relevant links
    }];

  } catch (error) {
    console.error("Error fetching news:", error);
    throw error;
  }
};

export const sendToGoogleChat = async (webhookUrl: string, newsItem: NewsItem) => {
  if (!webhookUrl) throw new Error("Webhook URL no configurada.");

  const cardMessage = {
    cardsV2: [
      {
        cardId: "newsCard",
        card: {
          header: {
            title: newsItem.title,
            subtitle: `Fecha: ${newsItem.date}`,
            imageUrl: "https://www.gob.mx/cms/uploads/attachment/file/151/escudo-nacional.png",
            imageType: "CIRCLE"
          },
          sections: [
            {
              header: "Resumen de Noticias",
              widgets: [
                {
                  textParagraph: {
                    text: newsItem.fullText
                  }
                }
              ]
            },
            {
              header: "Fuentes y Enlaces",
              widgets: newsItem.links.map(link => ({
                buttonList: {
                  buttons: [
                    {
                      text: link.title.substring(0, 40),
                      onClick: {
                        openLink: {
                          url: link.uri
                        }
                      }
                    }
                  ]
                }
              }))
            }
          ]
        }
      }
    ]
  };

  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(cardMessage)
  });

  if (!response.ok) {
    throw new Error(`Error al enviar a Google Chat: ${response.statusText}`);
  }

  return await response.json();
};

import React, { useState, useEffect, useCallback } from 'react';
