      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-40 px-4 md:px-8 py-4 glass">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-600 p-2 rounded-lg shadow-lg">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">FiscalNews Mexico</h1>
              <p className="text-xs text-slate-500 font-medium uppercase">Automatización Inteligente</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setShowSettings(!showSettings)}
              className="p-2 text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 rounded-full transition-all"
            >
              <SettingsIcon size={22} />
            </button>
            <button 
              onClick={handleSearch}
              disabled={isLoading}
              className="bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-300 text-white px-5 py-2 rounded-full font-semibold flex items-center gap-2 shadow-md transition-all"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Search size={20} />}
              <span className="hidden sm:inline">Actualizar Noticias</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto p-4 md:p-8 space-y-8">
        {/* Alerts */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
            <AlertCircle className="text-red-500" />
            <p className="text-red-700 text-sm font-medium">{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-400">×</button>
          </div>
        )}
        {successMsg && (
          <div className="bg-emerald-50 border-l-4 border-emerald-500 p-4 rounded-r-lg flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
            <CheckCircle2 className="text-emerald-500" />
            <p className="text-emerald-700 text-sm font-medium">{successMsg}</p>
            <button onClick={() => setSuccessMsg(null)} className="ml-auto text-emerald-400">×</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <div className="flex items-center gap-2 mb-4 text-slate-800 font-bold">
                <Filter size={18} className="text-emerald-600" />
                <h2>Fuentes / Temas</h2>
              </div>
              <div className="flex flex-wrap gap-2">
                {TOPICS_LIST.map(topic => (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
                      settings.selectedTopics.includes(topic)
                        ? 'bg-emerald-600 text-white shadow-sm'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    {topic}
                  </button>
                ))}
              </div>
            </section>
          </aside>

          {/* Results Area */}
          <div className="lg:col-span-3 space-y-6">
            {isLoading && results.length === 0 ? (
              <div className="space-y-4">
                {[1, 2].map(i => (
                  <div key={i} className="bg-white p-8 rounded-2xl border border-slate-100 animate-pulse">
                    <div className="h-6 bg-slate-200 rounded w-1/3 mb-4"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-2/3"></div>
                  </div>
                ))}
              </div>
            ) : results.length > 0 ? (
              results.map(item => (
                <article key={item.id} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                  <div className="p-8">
                    <div className="flex justify-between items-start mb-4">
                      <span className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-full text-xs font-bold uppercase border border-emerald-100">
                        {item.topic}
                      </span>
                      <span className="text-slate-400 text-sm">{item.date}</span>
                    </div>

                    <div className="prose prose-slate max-w-none text-slate-600 mb-8">
                      {/* Usamos ReactMarkdown para que el texto de Gemini se vea bien en la web */}
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {item.fullText}
                      </ReactMarkdown>
                    </div>

                    {item.links.length > 0 && (
                      <div className="border-t pt-6">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Enlaces directos</h4>
                        <div className="flex flex-wrap gap-3">
                          {item.links.map((link, idx) => (
                            <a 
                              key={idx}
                              href={link.uri}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center gap-2 text-sm text-emerald-600 hover:bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100 transition-all"
                            >
                              <span className="truncate max-w-[200px] font-medium">{link.title}</span>
                              <ExternalLink size={14} />
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                  <div className="bg-slate-50 px-8 py-4 flex justify-end items-center gap-4">
                    <button 
                      onClick={() => setResults([])}
                      className="text-slate-400 hover:text-red-500 text-sm font-medium flex items-center gap-1.5"
                    >
                      <Trash2 size={16} />
                      Limpiar
                    </button>
                    <button 
                      onClick={() => handleSendToChat(item)}
                      disabled={isLoading}
                      className="bg-slate-900 hover:bg-black text-white px-6 py-2 rounded-full font-bold text-sm flex items-center gap-2 shadow-lg transition-all active:scale-95"
                    >
                      {isLoading ? <Loader2 className="animate-spin" size={16} /> : <Send size={16} />}
                      Enviar a Google Chat
                    </button>
                  </div>
                </article>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
                <Search className="text-slate-300 mb-6" size={60} />
                <h2 className="text-xl font-bold text-slate-800 mb-2">Listo para automatizar</h2>
                <p className="text-slate-500 max-w-sm">
                  Presiona el botón de búsqueda para obtener los últimos resúmenes de SAT, IMSS e Infonavit.
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">Conexión Google Chat</h2>
                <button onClick={() => setShowSettings(false)} className="text-slate-400 text-2xl">&times;</button>
              </div>
              <div className="space-y-4">
                <label className="block text-sm font-bold text-slate-700">Webhook URL del Espacio</label>
                <input 
                  type="text" 
                  value={settings.googleChatWebhook}
                  onChange={(e) => setSettings(prev => ({ ...prev, googleChatWebhook: e.target.value }))}
                  placeholder="https://chat.googleapis.com/v1/spaces/..."
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-emerald-500 outline-none"
                />
                <p className="text-xs text-slate-400">
                  Copia esta URL desde la configuración de Webhooks en tu espacio de Google Chat.
                </p>
              </div>
            </div>
            <div className="p-8 bg-slate-50 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-emerald-200"
              >
                Listo
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface NewsItem {
  id: string;
  topic: string;
  title: string;
  summary: string;
  date: string;
  links: { title: string; uri: string }[];
  fullText: string;
}

export interface ScheduleSettings {
  enabled: boolean;
  startTime: string; // HH:mm format
  frequencyHours: number; // 0 for once, otherwise interval in hours
  lastRun: string | null; // ISO string
}

export interface AppSettings {
  googleChatWebhook: string;
  selectedTopics: string[];
  schedule: ScheduleSettings;
}

export enum Topic {
  SAT = 'SAT',
  IMSS = 'IMSS',
  INFONAVIT = 'Infonavit',
  UMA = 'UMA',
  IDSE = 'IDSE',
  CFDI = 'CFDI',
  SUA = 'SUA'
}

export const TOPICS_LIST = Object.values(Topic);

import React, { useState, useEffect, useRef } from 'react';
import { 
  Search, 
  Settings as SettingsIcon, 
  Send, 
  Bell, 
  ExternalLink, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  Filter,
  Newspaper,
  Clock,
  Zap,
  Calendar,
  Info
} from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { NewsItem, AppSettings, TOPICS_LIST, ScheduleSettings } from './types';
import { fetchFiscalNews, sendToGoogleChat } from './services/geminiService';

const DEFAULT_SCHEDULE: ScheduleSettings = {
  enabled: false,
  startTime: "09:00",
  frequencyHours: 0,
  lastRun: null
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedWebhook = localStorage.getItem('google_chat_webhook') || '';
    const savedTopics = JSON.parse(localStorage.getItem('selected_topics') || '["SAT", "IMSS", "Infonavit"]');
    const savedSchedule = JSON.parse(localStorage.getItem('schedule_settings') || JSON.stringify(DEFAULT_SCHEDULE));
    return {
      googleChatWebhook: savedWebhook,
      selectedTopics: savedTopics,
      schedule: savedSchedule
    };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [results, setResults] = useState<NewsItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [nextExecution, setNextExecution] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    localStorage.setItem('google_chat_webhook', settings.googleChatWebhook);
    localStorage.setItem('selected_topics', JSON.stringify(settings.selectedTopics));
    localStorage.setItem('schedule_settings', JSON.stringify(settings.schedule));
  }, [settings]);

  // Main search and send logic used by both manual and auto
  const runAutomationTask = async (isAuto = false) => {
    if (settings.selectedTopics.length === 0) {
      if (!isAuto) setError("Por favor selecciona al menos un tema.");
      return;
    }

    if (isAuto && !settings.googleChatWebhook) return;

    setIsLoading(true);
    setError(null);

    try {
      const news = await fetchFiscalNews(settings.selectedTopics);
      setResults(news);

      // If it's auto, send immediately to Google Chat
      if (isAuto && settings.googleChatWebhook && news.length > 0) {
        await sendToGoogleChat(settings.googleChatWebhook, news[0]);
        setSuccessMsg(`Automatización ejecutada: Noticia enviada a Google Chat.`);
      }

      // Update last run
      setSettings(prev => ({
        ...prev,
        schedule: { ...prev.schedule, lastRun: new Date().toISOString() }
      }));

    } catch (err: any) {
      const msg = err.message || "Error en la automatización.";
      if (!isAuto) setError(msg);
      console.error("Auto Error:", msg);
    } finally {
      setIsLoading(false);
    }
  };

  // Scheduling Logic (Tab must be open)
  useEffect(() => {
    const interval = setInterval(() => {
      if (!settings.schedule.enabled) {
        setNextExecution(null);
        return;
      }

      const now = new Date();
      const currentHMin = now.getHours().toString().padStart(2, '0') + ":" + now.getMinutes().toString().padStart(2, '0');

      // Check if it's time to run
      // For simplicity, we trigger if current time matches startTime and hasn't run in the last hour
      // OR if frequency is set, check if enough time has passed since lastRun
      const lastRunDate = settings.schedule.lastRun ? new Date(settings.schedule.lastRun) : null;
      const hoursSinceLastRun = lastRunDate ? (now.getTime() - lastRunDate.getTime()) / (1000 * 60 * 60) : 999;

      let shouldRun = false;

      if (currentHMin === settings.schedule.startTime) {
        if (!lastRunDate || lastRunDate.toDateString() !== now.toDateString()) {
          shouldRun = true;
        }
      } else if (settings.schedule.frequencyHours > 0 && lastRunDate) {
        if (hoursSinceLastRun >= settings.schedule.frequencyHours) {
          shouldRun = true;
        }
      }

      if (shouldRun && !isLoading) {
        console.log("Triggering scheduled execution...");
        runAutomationTask(true);
      }

      // Update next execution display
      setNextExecution(calculateNextRun(settings.schedule));

    }, 30000); // Check every 30 seconds

    return () => clearInterval(interval);
  }, [settings.schedule, settings.selectedTopics, settings.googleChatWebhook, isLoading]);

  const calculateNextRun = (sched: ScheduleSettings) => {
    if (!sched.enabled) return null;
    const now = new Date();
    const [h, m] = sched.startTime.split(':').map(Number);
    const todayStart = new Date();
    todayStart.setHours(h, m, 0, 0);

    if (todayStart > now) return todayStart.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });

    if (sched.frequencyHours > 0 && sched.lastRun) {
      const next = new Date(new Date(sched.lastRun).getTime() + sched.frequencyHours * 60 * 60 * 1000);
      return next.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: 'short' });
    }

    const tomorrow = new Date(todayStart.getTime() + 24 * 60 * 60 * 1000);
    return `Mañana ${tomorrow.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' })}`;
  };

  const toggleTopic = (topic: string) => {
    setSettings(prev => ({
      ...prev,
      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  const updateSchedule = (key: keyof ScheduleSettings, value: any) => {
    setSettings(prev => ({
      ...prev,
      schedule: { ...prev.schedule, [key]: value }
    }));
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-40 px-4 md:px-8 py-4 glass">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-600 p-2 rounded-lg shadow-lg">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-800 tracking-tight">FiscalNews Mexico</h1>
              <p className="text-xs text-slate-500 font-medium uppercase flex items-center gap-1">
                <Zap size={10} className="fill-emerald-500 text-emerald-500" />
                Automatización Inteligente
              </p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {nextExecution && (
              <div className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-emerald-50 text-emerald-700 rounded-full text-xs font-bold border border-emerald-100">
                <Clock size={14} />
                Próxima: {nextExecution}
              </div>
            )}
            <button 
              onClick={() => setShowSettings(!showSettings)}
              className="p-2 text-slate-500 hover:text-emerald-600 hover:bg-emerald-50 rounded-full transition-all"
            >
              <SettingsIcon size={22} />
            </button>
            <button 
              onClick={() => runAutomationTask(false)}
              disabled={isLoading}
              className="bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-300 text-white px-5 py-2 rounded-full font-semibold flex items-center gap-2 shadow-md transition-all active:scale-95"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Search size={20} />}
              <span className="hidden sm:inline">Buscar Ahora</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto p-4 md:p-8 space-y-8">
        {/* Alerts */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
            <AlertCircle className="text-red-500" />
            <p className="text-red-700 text-sm font-medium">{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-400">×</button>
          </div>
        )}
        {successMsg && (
          <div className="bg-emerald-50 border-l-4 border-emerald-500 p-4 rounded-r-lg flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
            <CheckCircle2 className="text-emerald-500" />
            <p className="text-emerald-700 text-sm font-medium">{successMsg}</p>
            <button onClick={() => setSuccessMsg(null)} className="ml-auto text-emerald-400">×</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            {/* Topics Filter */}
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <div className="flex items-center gap-2 mb-4 text-slate-800 font-bold">
                <Filter size={18} className="text-emerald-600" />
                <h2>Fuentes y Temas</h2>
              </div>
              <div className="flex flex-wrap gap-2">
                {TOPICS_LIST.map(topic => (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${
                      settings.selectedTopics.includes(topic)
                        ? 'bg-emerald-600 text-white shadow-sm'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    {topic}
                  </button>
                ))}
              </div>
            </section>

            {/* Automation Scheduler Card */}
            <section className="bg-slate-900 p-6 rounded-2xl shadow-xl text-white relative overflow-hidden">
              <div className="absolute -right-4 -top-4 text-white/5 rotate-12">
                <Clock size={120} />
              </div>

              <div className="relative z-10">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-2">
                    <Bell size={18} className="text-emerald-400" />
                    <h2 className="font-bold">Programación</h2>
                  </div>
                  <button 
                    onClick={() => updateSchedule('enabled', !settings.schedule.enabled)}
                    className={`w-10 h-6 rounded-full transition-colors relative ${settings.schedule.enabled ? 'bg-emerald-500' : 'bg-slate-700'}`}
                  >
                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.schedule.enabled ? 'left-5' : 'left-1'}`} />
                  </button>
                </div>

                <div className="space-y-4 opacity-90">
                  <div>
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-1.5">Hora de inicio</label>
                    <input 
                      type="time" 
                      value={settings.schedule.startTime}
                      onChange={(e) => updateSchedule('startTime', e.target.value)}
                      className="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-sm w-full focus:ring-1 focus:ring-emerald-500 outline-none"
                    />
                  </div>

                  <div>
                    <label className="text-xs font-bold text-slate-400 uppercase block mb-1.5">Frecuencia</label>
                    <select 
                      value={settings.schedule.frequencyHours}
                      onChange={(e) => updateSchedule('frequencyHours', parseInt(e.target.value))}
                      className="bg-slate-800 border border-slate-700 rounded-lg px-3 py-1.5 text-sm w-full focus:ring-1 focus:ring-emerald-500 outline-none"
                    >
                      <option value={0}>Solo una vez al día</option>
                      <option value={4}>Cada 4 horas</option>
                      <option value={8}>Cada 8 horas</option>
                      <option value={12}>Cada 12 horas</option>
                    </select>
                  </div>

                  {settings.schedule.enabled && (
                    <div className="pt-2">
                      <div className="flex items-center gap-2 text-emerald-400 text-xs font-bold bg-emerald-400/10 p-2 rounded-lg border border-emerald-400/20">
                        <Calendar size={14} />
                        Próxima: {nextExecution || 'Calculando...'}
                      </div>
                    </div>
                  )}

                  <div className="mt-4 p-3 bg-white/5 rounded-lg border border-white/5 flex gap-2">
                    <Info size={14} className="shrink-0 text-slate-400 mt-0.5" />
                    <p className="text-[10px] text-slate-400 leading-tight">
                      Para que la automatización funcione, mantén esta pestaña del navegador abierta.
                    </p>
                  </div>
                </div>
              </div>
            </section>
          </aside>

          {/* Results Area */}
          <div className="lg:col-span-3 space-y-6">
            {isLoading && results.length === 0 ? (
              <div className="space-y-4">
                {[1, 2].map(i => (
                  <div key={i} className="bg-white p-8 rounded-2xl border border-slate-100 animate-pulse">
                    <div className="h-6 bg-slate-200 rounded w-1/3 mb-4"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-2/3"></div>
                  </div>
                ))}
              </div>
            ) : results.length > 0 ? (
              results.map(item => (
                <article key={item.id} className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden group hover:shadow-xl transition-all duration-300">
                  <div className="p-8 md:p-10">
                    <div className="flex flex-wrap justify-between items-start gap-4 mb-6">
                      <div className="flex gap-2">
                        <span className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-full text-xs font-bold uppercase border border-emerald-100">
                          {item.topic}
                        </span>
                        {settings.schedule.enabled && (
                          <span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold uppercase border border-indigo-100 flex items-center gap-1">
                            <Zap size={10} /> Auto
                          </span>
                        )}
                      </div>
                      <span className="text-slate-400 text-sm font-medium flex items-center gap-1.5">
                        <Calendar size={14} />
                        {item.date}
                      </span>
                    </div>

                    <div className="prose prose-slate max-w-none text-slate-600 mb-8 prose-headings:text-slate-900 prose-strong:text-emerald-700">
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {item.fullText}
                      </ReactMarkdown>
                    </div>

                    {item.links.length > 0 && (
                      <div className="border-t border-slate-50 pt-8">
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-5">Fuentes Oficiales Seleccionadas</h4>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {item.links.map((link, idx) => (
                            <a 
                              key={idx}
                              href={link.uri}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center justify-between gap-3 text-sm text-slate-600 hover:text-emerald-700 hover:bg-emerald-50/50 p-3 rounded-xl border border-slate-100 hover:border-emerald-200 transition-all group/link"
                            >
                              <span className="truncate font-medium">{link.title}</span>
                              <ExternalLink size={14} className="shrink-0 text-slate-300 group-hover/link:text-emerald-500" />
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                  <div className="bg-slate-50/50 px-8 py-5 flex flex-wrap justify-end items-center gap-4 border-t border-slate-100">
                    <button 
                      onClick={() => setResults([])}
                      className="text-slate-400 hover:text-red-500 text-sm font-semibold flex items-center gap-1.5 transition-colors"
                    >
                      <Trash2 size={16} />
                      Descartar reporte
                    </button>
                    <button 
                      onClick={() => {
                        const webhookUrl = settings.googleChatWebhook;
                        if (!webhookUrl) {
                          setShowSettings(true);
                          setError("Configura el Webhook antes de enviar.");
                        } else {
                          sendToGoogleChat(webhookUrl, item)
                            .then(() => {
                              setSuccessMsg("Enviado manualmente a Google Chat.");
                              setTimeout(() => setSuccessMsg(null), 3000);
                            })
                            .catch(() => setError("Error al enviar. Revisa el webhook."));
                        }
                      }}
                      disabled={isLoading}
                      className="bg-slate-900 hover:bg-black text-white px-8 py-3 rounded-2xl font-bold text-sm flex items-center gap-2 shadow-lg transition-all active:scale-95 disabled:opacity-50"
                    >
                      <Send size={16} />
                      Reenviar a Google Chat
                    </button>
                  </div>
                </article>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-24 text-center bg-white rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-400 to-indigo-400 opacity-20"></div>
                <div className="bg-slate-50 p-8 rounded-full mb-8">
                  <Search className="text-slate-200" size={64} />
                </div>
                <h2 className="text-2xl font-black text-slate-800 mb-3">Tu Monitor Fiscal</h2>
                <p className="text-slate-400 max-w-sm mb-8 leading-relaxed">
                  Las noticias de <span className="text-emerald-600 font-bold italic">SAT, IMSS e Infonavit</span> aparecerán aquí resumidas por IA.
                </p>
                <button 
                  onClick={() => runAutomationTask(false)}
                  className="bg-white border-2 border-emerald-600 text-emerald-600 px-8 py-3 rounded-2xl font-bold hover:bg-emerald-600 hover:text-white transition-all shadow-lg shadow-emerald-100"
                >
                  Buscar ahora mismo
                </button>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 border-b border-slate-50">
              <div className="flex justify-between items-center mb-10">
                <div>
                  <h2 className="text-3xl font-black text-slate-900">Configuración</h2>
                  <p className="text-slate-500 text-sm mt-1">Vincula tus herramientas de trabajo.</p>
                </div>
                <button onClick={() => setShowSettings(false)} className="text-slate-300 hover:text-slate-900 text-3xl transition-colors">&times;</button>
              </div>

              <div className="space-y-8">
                <div>
                  <label className="block text-sm font-black text-slate-800 mb-3 uppercase tracking-wider">URL del Webhook de Google Chat</label>
                  <div className="relative group">
                    <input 
                      type="text" 
                      value={settings.googleChatWebhook}
                      onChange={(e) => setSettings(prev => ({ ...prev, googleChatWebhook: e.target.value }))}
                      placeholder="https://chat.googleapis.com/v1/spaces/..."
                      className="w-full px-5 py-4 rounded-2xl border-2 border-slate-100 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-50 outline-none transition-all pr-12 font-mono text-sm"
                    />
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-emerald-500 transition-colors">
                      <Zap size={20} />
                    </div>
                  </div>
                  <div className="mt-4 flex gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                    <Info size={18} className="text-indigo-600 shrink-0 mt-0.5" />
                    <div className="text-xs text-indigo-700 space-y-2">
                      <p><strong>¿Cómo obtenerlo?</strong></p>
                      <ol className="list-decimal list-inside space-y-1 opacity-80">
                        <li>Ve a tu espacio de Google Chat.</li>
                        <li>Haz clic en el nombre del espacio > Apps e integraciones.</li>
                        <li>Selecciona "Webhooks" y crea uno nuevo.</li>
                        <li>Copia la URL generada aquí.</li>
                      </ol>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div className="p-10 bg-slate-50 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-slate-900 text-white px-10 py-4 rounded-2xl font-black shadow-xl shadow-slate-200 hover:bg-black transition-all active:scale-95"
              >
                Guardar y Cerrar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface NewsItem {
  id: string;
  topic: string;
  title: string;
  summary: string;
  date: string;
  links: { title: string; uri: string }[];
  fullText: string;
}

export interface ScheduleSettings {
  enabled: boolean;
  startTime: string; // HH:mm format
  timesPerDay: number; // 1, 2, 3, 4, 6, 8, 12
  lastRun: string | null; // ISO string
}

export interface AppSettings {
  googleChatWebhook: string;
  selectedTopics: string[];
  schedule: ScheduleSettings;
}

export enum Topic {
  SAT = 'SAT',
  IMSS = 'IMSS',
  INFONAVIT = 'Infonavit',
  UMA = 'UMA',
  IDSE = 'IDSE',
  CFDI = 'CFDI',
  SUA = 'SUA'
}

export const TOPICS_LIST = Object.values(Topic);

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Search, 
  Settings as SettingsIcon, 
  Send, 
  Bell, 
  ExternalLink, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  Filter,
  Newspaper,
  Clock,
  Zap,
  Calendar,
  Info,
  ChevronRight,
  Activity
} from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { NewsItem, AppSettings, TOPICS_LIST, ScheduleSettings } from './types';
import { fetchFiscalNews, sendToGoogleChat } from './services/geminiService';

const DEFAULT_SCHEDULE: ScheduleSettings = {
  enabled: false,
  startTime: "09:00",
  timesPerDay: 1,
  lastRun: null
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedWebhook = localStorage.getItem('google_chat_webhook') || '';
    const savedTopics = JSON.parse(localStorage.getItem('selected_topics') || '["SAT", "IMSS", "Infonavit"]');
    const savedSchedule = JSON.parse(localStorage.getItem('schedule_settings') || JSON.stringify(DEFAULT_SCHEDULE));
    return {
      googleChatWebhook: savedWebhook,
      selectedTopics: savedTopics,
      schedule: savedSchedule
    };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [results, setResults] = useState<NewsItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [nextExecution, setNextExecution] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    localStorage.setItem('google_chat_webhook', settings.googleChatWebhook);
    localStorage.setItem('selected_topics', JSON.stringify(settings.selectedTopics));
    localStorage.setItem('schedule_settings', JSON.stringify(settings.schedule));
  }, [settings]);

  const runAutomationTask = useCallback(async (isAuto = false) => {
    if (settings.selectedTopics.length === 0) {
      if (!isAuto) setError("Por favor selecciona al menos un tema.");
      return;
    }

    if (isAuto && !settings.googleChatWebhook) return;

    setIsLoading(true);
    setError(null);

    try {
      const news = await fetchFiscalNews(settings.selectedTopics);
      setResults(news);

      if (isAuto && settings.googleChatWebhook && news.length > 0) {
        await sendToGoogleChat(settings.googleChatWebhook, news[0]);
        setSuccessMsg(`Automatización: Noticia enviada a Google Chat.`);
        setTimeout(() => setSuccessMsg(null), 5000);
      }

      setSettings(prev => ({
        ...prev,
        schedule: { ...prev.schedule, lastRun: new Date().toISOString() }
      }));

    } catch (err: any) {
      const msg = err.message || "Error en la automatización.";
      if (!isAuto) setError(msg);
      console.error("Auto Error:", msg);
    } finally {
      setIsLoading(false);
    }
  }, [settings.selectedTopics, settings.googleChatWebhook]);

  // Precise scheduling logic
  useEffect(() => {
    const checkSchedule = () => {
      if (!settings.schedule.enabled) {
        setNextExecution(null);
        return;
      }

      const now = new Date();
      const [startH, startM] = settings.schedule.startTime.split(':').map(Number);
      const intervalHours = 24 / settings.schedule.timesPerDay;

      // Calculate all daily execution slots
      const slots: Date[] = [];
      for (let i = 0; i < settings.schedule.timesPerDay; i++) {
        const slot = new Date();
        slot.setHours(startH + (i * intervalHours), startM, 0, 0);
        // If the slot calculation rolls over to next day, that's fine, we sort later
        slots.push(slot);
      }

      // Sort slots by time
      slots.sort((a, b) => a.getTime() - b.getTime());

      // Find the next upcoming slot
      let targetSlot = slots.find(s => s > now);
      if (!targetSlot) {
        // All today's slots passed, take the first one but for tomorrow
        targetSlot = new Date(slots[0]);
        targetSlot.setDate(targetSlot.getDate() + 1);
      }

      setNextExecution(targetSlot.toLocaleTimeString('es-MX', { 
        hour: '2-digit', 
        minute: '2-digit',
        day: targetSlot.getDate() !== now.getDate() ? '2-digit' : undefined,
        month: targetSlot.getDate() !== now.getDate() ? 'short' : undefined
      }));

      // Check if we should trigger now
      // Trigger if current time is within 1 minute of ANY slot AND we haven't run in the last 10 mins
      const lastRunDate = settings.schedule.lastRun ? new Date(settings.schedule.lastRun) : null;
      const minsSinceLastRun = lastRunDate ? (now.getTime() - lastRunDate.getTime()) / (1000 * 60) : 999;

      const isSlotTime = slots.some(slot => {
        const diff = Math.abs(now.getTime() - slot.getTime()) / (1000 * 60);
        return diff < 1; // within 1 minute
      });

      if (isSlotTime && minsSinceLastRun > 10 && !isLoading) {
        runAutomationTask(true);
      }
    };

    const interval = setInterval(checkSchedule, 30000); // Check every 30s
    checkSchedule(); // Initial check

    return () => clearInterval(interval);
  }, [settings.schedule, isLoading, runAutomationTask]);

  const toggleTopic = (topic: string) => {
    setSettings(prev => ({
      ...prev,
      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  const updateSchedule = (key: keyof ScheduleSettings, value: any) => {
    setSettings(prev => ({
      ...prev,
      schedule: { ...prev.schedule, [key]: value }
    }));
  };

  return (
    <div className="min-h-screen pb-20 bg-slate-50/50">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-40 px-4 md:px-8 py-4 glass">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-600 p-2.5 rounded-xl shadow-lg shadow-emerald-100 transform -rotate-3 group hover:rotate-0 transition-transform cursor-pointer">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-800 tracking-tight leading-none mb-1">FiscalBot MX</h1>
              <div className="flex items-center gap-2">
                <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">IA en Tiempo Real</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden lg:flex items-center gap-6 px-6 py-2 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Estado</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                   <Activity size={12} className="text-emerald-500" /> Sistema Activo
                </span>
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Próximo Envío</span>
                <span className="text-xs font-bold text-emerald-600 flex items-center gap-1.5">
                   <Clock size={12} /> {nextExecution || 'Manual'}
                </span>
              </div>
            </div>

            <button 
              onClick={() => setShowSettings(true)}
              className="p-3 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
            >
              <SettingsIcon size={20} />
            </button>

            <button 
              onClick={() => runAutomationTask(false)}
              disabled={isLoading}
              className="bg-slate-900 hover:bg-black disabled:bg-slate-400 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-slate-200 transition-all active:scale-95"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={18} className="fill-current" />}
              <span className="hidden sm:inline">Buscar Ahora</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 md:p-8 space-y-8">
        {/* Alerts */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-red-500 p-2 rounded-lg text-white">
               <AlertCircle size={20} />
            </div>
            <p className="text-red-700 text-sm font-bold">{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-300 hover:text-red-500 text-xl">&times;</button>
          </div>
        )}
        {successMsg && (
          <div className="bg-emerald-50 border-l-4 border-emerald-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-emerald-500 p-2 rounded-lg text-white">
               <CheckCircle2 size={20} />
            </div>
            <p className="text-emerald-700 text-sm font-bold">{successMsg}</p>
            <button onClick={() => setSuccessMsg(null)} className="ml-auto text-emerald-300 hover:text-emerald-500 text-xl">&times;</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Left Column: Config */}
          <aside className="lg:col-span-4 space-y-6">
            {/* Automation Scheduler Card - Updated for "Times per day" */}
            <section className="bg-emerald-600 p-8 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden group">
              <div className="absolute -right-10 -bottom-10 text-white/10 group-hover:scale-110 transition-transform duration-700">
                <Clock size={200} />
              </div>

              <div className="relative z-10">
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-3">
                    <div className="bg-white/20 p-2 rounded-lg">
                      <Bell size={20} className="text-white" />
                    </div>
                    <h2 className="text-xl font-black">Autoprogramar</h2>
                  </div>
                  <button 
                    onClick={() => updateSchedule('enabled', !settings.schedule.enabled)}
                    className={`w-12 h-6 rounded-full transition-colors relative flex items-center ${settings.schedule.enabled ? 'bg-white' : 'bg-emerald-800'}`}
                  >
                    <div className={`absolute w-5 h-5 rounded-full transition-all shadow-md ${settings.schedule.enabled ? 'left-6 bg-emerald-600' : 'left-1 bg-white'}`} />
                  </button>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Primera actualización</label>
                    <div className="relative">
                      <input 
                        type="time" 
                        value={settings.schedule.startTime}
                        onChange={(e) => updateSchedule('startTime', e.target.value)}
                        className="bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm w-full focus:ring-2 focus:ring-white outline-none font-bold text-white transition-all"
                      />
                      <Clock className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40" size={16} />
                    </div>
                  </div>

                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Frecuencia de envío</label>
                    <div className="grid grid-cols-2 gap-2">
                      {[1, 2, 3, 4, 6, 12].map(num => (
                        <button
                          key={num}
                          onClick={() => updateSchedule('timesPerDay', num)}
                          className={`px-3 py-2.5 rounded-xl text-xs font-black border transition-all ${
                            settings.schedule.timesPerDay === num 
                            ? 'bg-white text-emerald-700 border-white' 
                            : 'bg-white/5 border-white/10 hover:bg-white/10'
                          }`}
                        >
                          {num} {num === 1 ? 'Vez' : 'Veces'} / día
                        </button>
                      ))}
                    </div>
                  </div>

                  {settings.schedule.enabled && (
                    <div className="pt-2 animate-in fade-in zoom-in-95">
                      <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10 flex items-center gap-4">
                        <div className="bg-emerald-400 p-2 rounded-lg text-emerald-900 shadow-inner">
                          <Calendar size={18} />
                        </div>
                        <div>
                          <p className="text-[10px] font-bold text-white/60 uppercase leading-none mb-1">Próxima Alerta</p>
                          <p className="text-sm font-black text-white leading-none">{nextExecution}</p>
                        </div>
                        <ChevronRight className="ml-auto text-white/30" size={18} />
                      </div>
                    </div>
                  )}

                  <div className="flex gap-3 p-4 bg-emerald-700/50 rounded-2xl border border-emerald-400/20">
                    <Info size={16} className="shrink-0 text-emerald-300 mt-0.5" />
                    <p className="text-[10px] text-emerald-100/80 leading-relaxed font-medium">
                      Nota: Para que el sistema trabaje solo, la pestaña del navegador debe permanecer abierta.
                    </p>
                  </div>
                </div>
              </div>
            </section>

            {/* Topics Filter */}
            <section className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
              <div className="flex items-center gap-3 mb-6 text-slate-800 font-black">
                <div className="bg-slate-50 p-2 rounded-lg">
                  <Filter size={20} className="text-emerald-600" />
                </div>
                <h2>Temas a Monitorizar</h2>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {TOPICS_LIST.map(topic => (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`px-4 py-3 rounded-xl text-xs font-black transition-all border ${
                      settings.selectedTopics.includes(topic)
                        ? 'bg-slate-900 text-white border-slate-900 shadow-lg shadow-slate-200'
                        : 'bg-slate-50 text-slate-500 border-slate-100 hover:bg-slate-100'
                    }`}
                  >
                    {topic}
                  </button>
                ))}
              </div>
            </section>
          </aside>

          {/* Right Column: Feed */}
          <div className="lg:col-span-8 space-y-6">
            {isLoading && results.length === 0 ? (
              <div className="space-y-6">
                {[1, 2].map(i => (
                  <div key={i} className="bg-white p-10 rounded-[2.5rem] border border-slate-100 animate-pulse">
                    <div className="h-4 bg-slate-100 rounded w-24 mb-6"></div>
                    <div className="h-8 bg-slate-200 rounded w-3/4 mb-4"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : results.length > 0 ? (
              results.map(item => (
                <article key={item.id} className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden group hover:shadow-2xl hover:-translate-y-1 transition-all duration-500">
                  <div className="p-10">
                    <div className="flex flex-wrap justify-between items-start gap-4 mb-8">
                      <div className="flex gap-2">
                        <span className="bg-emerald-50 text-emerald-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-100">
                          {item.topic}
                        </span>
                        {settings.schedule.enabled && (
                          <span className="bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100 flex items-center gap-2">
                            <Activity size={12} className="animate-pulse" /> Autopilot
                          </span>
                        )}
                      </div>
                      <span className="text-slate-400 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                        <Calendar size={14} className="text-slate-300" />
                        {item.date}
                      </span>
                    </div>

                    <div className="prose prose-slate max-w-none text-slate-600 mb-10 prose-headings:font-black prose-headings:text-slate-900 prose-strong:text-emerald-700 prose-li:marker:text-emerald-400">
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {item.fullText}
                      </ReactMarkdown>
                    </div>

                    {item.links.length > 0 && (
                      <div className="border-t border-slate-100 pt-10">
                        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Fuentes Verificadas</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {item.links.map((link, idx) => (
                            <a 
                              key={idx}
                              href={link.uri}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center justify-between gap-4 p-4 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-emerald-50 hover:border-emerald-200 transition-all group/link"
                            >
                              <div className="flex items-center gap-3 overflow-hidden">
                                <div className="bg-white p-2 rounded-lg text-emerald-600 shadow-sm">
                                   <ExternalLink size={14} />
                                </div>
                                <span className="truncate font-bold text-sm text-slate-700 group-hover/link:text-emerald-800">{link.title}</span>
                              </div>
                              <ChevronRight size={16} className="shrink-0 text-slate-300 group-hover/link:translate-x-1 group-hover/link:text-emerald-500 transition-all" />
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>

