import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Topic, NewsItem } from "../types";

const API_KEY = process.env.API_KEY || '';

export const fetchFiscalNews = async (topics: string[]): Promise<NewsItem[]> => {
  if (!API_KEY) {
    throw new Error("API Key no configurada.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = 'gemini-3-flash-preview';

  const topicsStr = topics.join(', ');
  const prompt = `
    Eres un experto en noticias fiscales y laborales en México.
    Busca y resume las noticias más recientes y confiables sobre: ${topicsStr}.

    Fuentes Prioritarias: SAT, IMSS, Infonavit, CONASAMI, El Universal, Milenio, Animal Político.

    REGLAS DE FORMATO (ESTRICTO):
    1. Usa Markdown estándar.
    2. Usa ### para subtítulos de noticias.
    3. Usa **negritas** para conceptos clave o fechas.
    4. Usa listas con guiones (-) para puntos importantes.
    5. NO inventes información. Si no hay noticias recientes de hoy, busca de la última semana.
    6. Al final del reporte, DEBES incluir una sección llamada "Fuentes Consultadas" con una lista de los medios de donde se obtuvo la información.

    IMPORTANTE: Asegúrate de que el reporte sea conciso pero informativo.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "No se encontró información.";

    // Extract links from grounding metadata to ensure we have the actual URLs
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    const links = chunks
      .filter(chunk => chunk.web)
      .map(chunk => ({
        title: chunk.web?.title || 'Fuente externa',
        uri: chunk.web?.uri || ''
      }))
      // Filter out duplicates
      .filter((link, index, self) => 
        index === self.findIndex((t) => t.uri === link.uri)
      );

    return [{
      id: crypto.randomUUID(),
      topic: topics.length > 1 ? "Resumen Fiscal" : topics[0],
      title: `Reporte Fiscal México: ${new Date().toLocaleDateString('es-MX')}`,
      summary: text.substring(0, 300) + "...",
      fullText: text,
      date: new Date().toLocaleDateString('es-MX'),
      links: links.slice(0, 10) // Allow more links for transparency
    }];

  } catch (error) {
    console.error("Error fetching news:", error);
    throw error;
  }
};

/**
 * Convierte Markdown estándar (**bold**) al formato de Google Chat (*bold*)
 * Google Chat requiere que los asteriscos no tengan espacios internos y 
 * usualmente funcionen mejor al inicio de línea o con espacios alrededor.
 */
const formatForGoogleChat = (text: string): string => {
  return text
    // 1. Convertir encabezados (### Titulo) a negritas de Google Chat (*Titulo*)
    .replace(/^#{1,4}\s+(.*?)$/gm, '*$1*')
    // 2. Convertir negritas dobles (**texto**) a negrita simple de Google Chat (*texto*)
    .replace(/\*\*(.*?)\*\*/g, '*$1*')
    // 3. Asegurar que las listas tengan un espacio limpio
    .replace(/^- /gm, '• ')
    // 4. Limpiar posibles triples asteriscos accidentales
    .replace(/\*\*\*/g, '*');
};

export const sendToGoogleChat = async (webhookUrl: string, newsItem: NewsItem) => {
  if (!webhookUrl) throw new Error("Webhook URL no configurada.");

  // Formateamos el cuerpo principal
  const formattedBody = formatForGoogleChat(newsItem.fullText);

  // Construcción de la sección de links con formato compatible
  let linksSection = "";
  if (newsItem.links.length > 0) {
    linksSection = `\n\n----------------------------------\n*📖 FUENTES Y LECTURA ADICIONAL:*\n\n`;
    linksSection += newsItem.links
      .map(l => `• *${l.title}*\n<${l.uri}>`)
      .join('\n\n');
  }

  // Google Chat interpreta *texto* como negrita solo si hay espacios o saltos de línea correctos
  const message = {
    text: `🔔 *${newsItem.title.toUpperCase()}*\n\n${formattedBody}${linksSection}\n\n_Generado automáticamente por FiscalBot MX_`
  };

  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(message)
  });

  if (!response.ok) {
    throw new Error(`Error al enviar a Google Chat: ${response.statusText}`);
  }

  return await response.json();
};

