import remarkGfm from 'remark-gfm';
import { NewsItem, AppSettings, TOPICS_LIST, ScheduleSettings } from './types';
import { fetchFiscalNews, sendToGoogleChat } from './services/geminiService';

const DEFAULT_SCHEDULE: ScheduleSettings = {
  enabled: false,
  startTime: "09:00",
  timesPerDay: 1,
  lastRun: null
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedWebhook = localStorage.getItem('google_chat_webhook') || '';
    const savedTopics = JSON.parse(localStorage.getItem('selected_topics') || '["SAT", "IMSS", "Infonavit"]');
    const savedSchedule = JSON.parse(localStorage.getItem('schedule_settings') || JSON.stringify(DEFAULT_SCHEDULE));
    return {
      googleChatWebhook: savedWebhook,
      selectedTopics: savedTopics,
      schedule: savedSchedule
    };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [results, setResults] = useState<NewsItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [nextExecution, setNextExecution] = useState<string | null>(null);

  // Detect browser timezone
  const userTimeZone = useMemo(() => {
    try {
      return Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch (e) {
      return 'UTC';
    }
  }, []);

  // Persistence
  useEffect(() => {
    localStorage.setItem('google_chat_webhook', settings.googleChatWebhook);
    localStorage.setItem('selected_topics', JSON.stringify(settings.selectedTopics));
    localStorage.setItem('schedule_settings', JSON.stringify(settings.schedule));
  }, [settings]);

  const runAutomationTask = useCallback(async (isAuto = false) => {
    if (settings.selectedTopics.length === 0) {
      if (!isAuto) setError("Por favor selecciona al menos un tema.");
      return;
    }

    if (isAuto && !settings.googleChatWebhook) return;

    setIsLoading(true);
    setError(null);

    try {
      const news = await fetchFiscalNews(settings.selectedTopics);
      setResults(news);

      if (isAuto && settings.googleChatWebhook && news.length > 0) {
        await sendToGoogleChat(settings.googleChatWebhook, news[0]);
        setSuccessMsg(`Automatización: Reporte enviado a Google Chat.`);
        setTimeout(() => setSuccessMsg(null), 5000);
      }

      setSettings(prev => ({
        ...prev,
        schedule: { ...prev.schedule, lastRun: new Date().toISOString() }
      }));

    } catch (err: any) {
      const msg = err.message || "Error en la automatización.";
      if (!isAuto) setError(msg);
      console.error("Auto Error:", msg);
    } finally {
      setIsLoading(false);
    }
  }, [settings.selectedTopics, settings.googleChatWebhook]);

  // Precise scheduling logic based on Local Time
  useEffect(() => {
    const checkSchedule = () => {
      if (!settings.schedule.enabled) {
        setNextExecution(null);
        return;
      }

      const now = new Date();
      const [startH, startM] = settings.schedule.startTime.split(':').map(Number);
      const intervalHours = 24 / settings.schedule.timesPerDay;

      const slots: Date[] = [];
      for (let i = 0; i < settings.schedule.timesPerDay; i++) {
        const slot = new Date();
        slot.setHours(startH + (i * intervalHours), startM, 0, 0);
        slots.push(slot);
      }

      slots.sort((a, b) => a.getTime() - b.getTime());

      let targetSlot = slots.find(s => s > now);
      if (!targetSlot) {
        targetSlot = new Date(slots[0]);
        targetSlot.setDate(targetSlot.getDate() + 1);
      }

      setNextExecution(targetSlot.toLocaleTimeString('es-MX', { 
        hour: '2-digit', 
        minute: '2-digit',
        day: targetSlot.getDate() !== now.getDate() ? '2-digit' : undefined,
        month: targetSlot.getDate() !== now.getDate() ? 'short' : undefined
      }));

      const lastRunDate = settings.schedule.lastRun ? new Date(settings.schedule.lastRun) : null;
      const minsSinceLastRun = lastRunDate ? (now.getTime() - lastRunDate.getTime()) / (1000 * 60) : 999;

      const isSlotTime = slots.some(slot => {
        const diff = Math.abs(now.getTime() - slot.getTime()) / (1000 * 60);
        return diff < 1; 
      });

      if (isSlotTime && minsSinceLastRun > 10 && !isLoading) {
        runAutomationTask(true);
      }
    };

    const interval = setInterval(checkSchedule, 30000); 
    checkSchedule(); 

    return () => clearInterval(interval);
  }, [settings.schedule, isLoading, runAutomationTask]);

  const toggleTopic = (topic: string) => {
    setSettings(prev => ({
      ...prev,
      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  const updateSchedule = (key: keyof ScheduleSettings, value: any) => {
    setSettings(prev => ({
      ...prev,
      schedule: { ...prev.schedule, [key]: value }
    }));
  };

  return (
    <div className="min-h-screen pb-20 bg-slate-50/50">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-40 px-4 md:px-8 py-4 glass">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-600 p-2.5 rounded-xl shadow-lg shadow-emerald-100 transform -rotate-3 group hover:rotate-0 transition-transform cursor-pointer">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-800 tracking-tight leading-none mb-1">FiscalBot MX</h1>
              <div className="flex items-center gap-2">
                <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">IA en Tiempo Real</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden lg:flex items-center gap-6 px-6 py-2 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Zona Horaria</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                   <Globe size={12} className="text-indigo-500" /> {userTimeZone}
                </span>
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Estado</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                   <Activity size={12} className="text-emerald-500" /> Sistema Activo
                </span>
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Próximo Envío</span>
                <span className="text-xs font-bold text-emerald-600 flex items-center gap-1.5">
                   <Clock size={12} /> {nextExecution || 'Manual'}
                </span>
              </div>
            </div>

            <button 
              onClick={() => setShowSettings(true)}
              className="p-3 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
            >
              <SettingsIcon size={20} />
            </button>

            <button 
              onClick={() => runAutomationTask(false)}
              disabled={isLoading}
              className="bg-slate-900 hover:bg-black disabled:bg-slate-400 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-slate-200 transition-all active:scale-95"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={18} className="fill-current" />}
              <span className="hidden sm:inline">Buscar Ahora</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 md:p-8 space-y-8">
        {/* Alerts */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-red-500 p-2 rounded-lg text-white">
               <AlertCircle size={20} />
            </div>
            <p className="text-red-700 text-sm font-bold">{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-300 hover:text-red-500 text-xl">&times;</button>
          </div>
        )}
        {successMsg && (
          <div className="bg-emerald-50 border-l-4 border-emerald-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-emerald-500 p-2 rounded-lg text-white">
               <CheckCircle2 size={20} />
            </div>
            <p className="text-emerald-700 text-sm font-bold">{successMsg}</p>
            <button onClick={() => setSuccessMsg(null)} className="ml-auto text-emerald-300 hover:text-emerald-500 text-xl">&times;</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Left Column: Config */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="bg-emerald-600 p-8 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden group">
              <div className="absolute -right-10 -bottom-10 text-white/10 group-hover:scale-110 transition-transform duration-700">
                <Clock size={200} />
              </div>

              <div className="relative z-10">
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-3">
                    <div className="bg-white/20 p-2 rounded-lg">
                      <Bell size={20} className="text-white" />
                    </div>
                    <h2 className="text-xl font-black">Autoprogramar</h2>
                  </div>
                  <button 
                    onClick={() => updateSchedule('enabled', !settings.schedule.enabled)}
                    className={`w-12 h-6 rounded-full transition-colors relative flex items-center ${settings.schedule.enabled ? 'bg-white' : 'bg-emerald-800'}`}
                  >
                    <div className={`absolute w-5 h-5 rounded-full transition-all shadow-md ${settings.schedule.enabled ? 'left-6 bg-emerald-600' : 'left-1 bg-white'}`} />
                  </button>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center gap-2 text-[10px] font-black text-emerald-100 uppercase tracking-widest bg-emerald-700/50 w-fit px-3 py-1 rounded-full border border-emerald-400/20">
                    <Globe size={12} /> Zona: {userTimeZone}
                  </div>

                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Primera actualización (Hora Local)</label>
                    <div className="relative">
                      <input 
                        type="time" 
                        value={settings.schedule.startTime}
                        onChange={(e) => updateSchedule('startTime', e.target.value)}
                        className="bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm w-full focus:ring-2 focus:ring-white outline-none font-bold text-white transition-all"
                      />
                      <Clock className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40" size={16} />
                    </div>
                  </div>

                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Frecuencia de envío</label>
                    <div className="grid grid-cols-2 gap-2">
                      {[1, 2, 3, 4, 6, 12].map(num => (
                        <button
                          key={num}
                          onClick={() => updateSchedule('timesPerDay', num)}
                          className={`px-3 py-2.5 rounded-xl text-xs font-black border transition-all ${
                            settings.schedule.timesPerDay === num 
                            ? 'bg-white text-emerald-700 border-white' 
                            : 'bg-white/5 border-white/10 hover:bg-white/10'
                          }`}
                        >
                          {num} {num === 1 ? 'Vez' : 'Veces'} / día
                        </button>
                      ))}
                    </div>
                  </div>

                  {settings.schedule.enabled && (
                    <div className="pt-2 animate-in fade-in zoom-in-95">
                      <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10 flex items-center gap-4">
                        <div className="bg-emerald-400 p-2 rounded-lg text-emerald-900 shadow-inner">
                          <Calendar size={18} />
                        </div>
                        <div>
                          <p className="text-[10px] font-bold text-white/60 uppercase leading-none mb-1">Próxima Alerta</p>
                          <p className="text-sm font-black text-white leading-none">{nextExecution}</p>
                        </div>
                        <ChevronRight className="ml-auto text-white/30" size={18} />
                      </div>
                    </div>
                  )}

                  <div className="flex gap-3 p-4 bg-emerald-700/50 rounded-2xl border border-emerald-400/20">
                    <Info size={16} className="shrink-0 text-emerald-300 mt-0.5" />
                    <p className="text-[10px] text-emerald-100/80 leading-relaxed font-medium">
                      El sistema usa tu hora local de <strong>{userTimeZone}</strong>. Mantén la pestaña abierta para procesar el envío.
                    </p>
                  </div>
                </div>
              </div>
            </section>

            <section className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
              <div className="flex items-center gap-3 mb-6 text-slate-800 font-black">
                <div className="bg-slate-50 p-2 rounded-lg">
                  <Filter size={20} className="text-emerald-600" />
                </div>
                <h2>Temas a Monitorizar</h2>
              </div>
              <div className="grid grid-cols-2 gap-2">
                {TOPICS_LIST.map(topic => (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`px-4 py-3 rounded-xl text-xs font-black transition-all border ${
                      settings.selectedTopics.includes(topic)
                        ? 'bg-slate-900 text-white border-slate-900 shadow-lg shadow-slate-200'
                        : 'bg-slate-50 text-slate-500 border-slate-100 hover:bg-slate-100'
                    }`}
                  >
                    {topic}
                  </button>
                ))}
              </div>
            </section>
          </aside>

          {/* Right Column: Feed */}
          <div className="lg:col-span-8 space-y-6">
            {isLoading && results.length === 0 ? (
              <div className="space-y-6">
                {[1, 2].map(i => (
                  <div key={i} className="bg-white p-10 rounded-[2.5rem] border border-slate-100 animate-pulse">
                    <div className="h-4 bg-slate-100 rounded w-24 mb-6"></div>
                    <div className="h-8 bg-slate-200 rounded w-3/4 mb-4"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : results.length > 0 ? (
              results.map(item => (
                <article key={item.id} className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden group hover:shadow-2xl hover:-translate-y-1 transition-all duration-500">
                  <div className="p-10">
                    <div className="flex flex-wrap justify-between items-start gap-4 mb-8">
                      <div className="flex gap-2">
                        <span className="bg-emerald-50 text-emerald-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-100">
                          {item.topic}
                        </span>
                        {settings.schedule.enabled && (
                          <span className="bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100 flex items-center gap-2">
                            <Activity size={12} className="animate-pulse" /> Autopilot
                          </span>
                        )}
                      </div>
                      <span className="text-slate-400 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                        <Calendar size={14} className="text-slate-300" />
                        {item.date}
                      </span>
                    </div>

                    <div className="prose prose-slate max-w-none text-slate-600 mb-10 prose-headings:font-black prose-headings:text-slate-900 prose-strong:text-emerald-700 prose-li:marker:text-emerald-400">
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {item.fullText}
                      </ReactMarkdown>
                    </div>

                    {item.links.length > 0 && (
                      <div className="border-t border-slate-100 pt-10">
                        <div className="flex items-center gap-3 mb-6">
                           <div className="bg-slate-100 p-2 rounded-lg text-slate-500">
                              <BookOpen size={16} />
                           </div>
                           <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Fuentes de Información y Lectura</h4>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {item.links.map((link, idx) => (
                            <a 
                              key={idx}
                              href={link.uri}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center justify-between gap-4 p-4 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-emerald-50 hover:border-emerald-200 transition-all group/link shadow-sm hover:shadow-md"
                            >
                              <div className="flex items-center gap-3 overflow-hidden">
                                <div className="bg-white p-2.5 rounded-xl text-emerald-600 shadow-sm border border-slate-100 group-hover/link:border-emerald-200">
                                   <ExternalLink size={14} />
                                </div>
                                <span className="truncate font-bold text-sm text-slate-700 group-hover/link:text-emerald-800">{link.title}</span>
                              </div>
                              <ChevronRight size={16} className="shrink-0 text-slate-300 group-hover/link:translate-x-1 group-hover/link:text-emerald-500 transition-all" />
                            </a>
                          ))}
                        </div>
                        <p className="mt-6 text-[10px] text-slate-400 italic text-center font-medium">Haz clic en cualquier fuente para leer la noticia completa en el portal oficial.</p>
                      </div>
                    )}
                  </div>

                  <div className="bg-slate-50/50 px-10 py-6 flex flex-wrap justify-between items-center gap-4 border-t border-slate-100">
                    <button 
                      onClick={() => setResults([])}
                      className="text-slate-400 hover:text-red-500 text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-colors"
                    >
                      <Trash2 size={16} />
                      Borrar reporte
                    </button>
                    <button 
                      onClick={() => {
                        if (!settings.googleChatWebhook) {
                          setShowSettings(true);
                          setError("Configura el Webhook en ajustes.");
                        } else {
                          sendToGoogleChat(settings.googleChatWebhook, item)
                            .then(() => {
                              setSuccessMsg("¡Reporte con fuentes enviado con éxito!");
                              setTimeout(() => setSuccessMsg(null), 3000);
                            })
                            .catch(() => setError("No se pudo enviar. Revisa el webhook."));
                        }
                      }}
                      disabled={isLoading}
                      className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 shadow-xl shadow-emerald-200 transition-all active:scale-95 disabled:opacity-50"
                    >
                      <Send size={16} />
                      Enviar a Google Chat
                    </button>
                  </div>
                </article>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-32 text-center bg-white rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-emerald-500 via-indigo-500 to-emerald-500 bg-[length:200%_100%] animate-[gradient_3s_linear_infinite]"></div>
                <div className="bg-slate-50 p-10 rounded-full mb-8 transform group-hover:scale-110 transition-transform duration-500">
                  <Search className="text-slate-200" size={80} />
                </div>
                <h2 className="text-3xl font-black text-slate-800 mb-4 tracking-tight">Monitor Fiscal Inteligente</h2>
                <p className="text-slate-400 max-w-sm mb-10 leading-relaxed font-medium">
                  Configura tu automatización o realiza una búsqueda manual para recibir resúmenes de <span className="text-emerald-600 font-black">SAT, IMSS e Infonavit</span>.
                </p>
                <button 
                  onClick={() => runAutomationTask(false)}
                  className="bg-slate-900 hover:bg-black text-white px-10 py-4 rounded-2xl font-black shadow-2xl shadow-slate-200 transition-all active:scale-95"
                >
                  Iniciar Búsqueda
                </button>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-lg animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-500">
            <div className="p-12 border-b border-slate-50">
              <div className="flex justify-between items-center mb-12">
                <div>
                  <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Conexiones</h2>
                  <p className="text-slate-500 text-sm mt-2 font-medium">Vincula tu espacio de Google Chat para la automatización.</p>
                </div>
                <button 
                  onClick={() => setShowSettings(false)} 
                  className="text-slate-300 hover:text-slate-900 text-4xl font-light transition-colors"
                >
                  &times;
                </button>
              </div>

              <div className="space-y-10">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-4 uppercase tracking-[0.2em]">Webhook de Google Chat</label>
                  <div className="relative group">
                    <input 
                      type="text" 
                      value={settings.googleChatWebhook}
                      onChange={(e) => setSettings(prev => ({ ...prev, googleChatWebhook: e.target.value }))}
                      placeholder="https://chat.googleapis.com/v1/spaces/..."
                      className="w-full px-6 py-5 rounded-[1.5rem] border-2 border-slate-100 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-50 outline-none transition-all pr-14 font-mono text-xs"
                    />
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-200 group-focus-within:text-emerald-500 transition-colors">
                      <Zap size={24} className="fill-current" />
                    </div>
                  </div>

                  <div className="mt-8 flex gap-5 p-6 bg-indigo-50 rounded-[2rem] border border-indigo-100 relative overflow-hidden">
                    <div className="absolute -right-4 -bottom-4 text-indigo-500/5">
                      <Info size={100} />
                    </div>
                    <Info size={24} className="text-indigo-600 shrink-0 mt-1" />
                    <div className="text-xs text-indigo-800 space-y-3 relative z-10">
                      <p className="font-black text-sm">¿Cómo configurar el envío automático?</p>
                      <ol className="list-decimal list-inside space-y-2 font-medium opacity-80 leading-relaxed">
                        <li>Entra a tu espacio de <span className="font-black">Google Chat</span>.</li>
                        <li>Haz clic en el nombre del espacio &gt; <span className="font-black">Apps e integraciones</span>.</li>
                        <li>Crea un nuevo <span className="font-black">Webhook</span> y copia la URL generada.</li>
                        <li>Pégala aquí arriba y activa la <span className="font-black text-emerald-600 italic">Programación</span> en el panel lateral.</li>
                      </ol>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div className="p-12 bg-slate-50 flex justify-end">
              <button 
                onClick={() => setShowSettings(false)}
                className="bg-slate-900 text-white px-12 py-5 rounded-[1.5rem] font-black shadow-2xl shadow-slate-200 hover:bg-black transition-all active:scale-95 uppercase tracking-widest text-xs"
              >
                Guardar Configuración
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes gradient {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Search, 
  Settings as SettingsIcon, 
  Send, 
  Bell, 
  ExternalLink, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  Filter,
  Newspaper,
  Clock,
  Zap,
  Calendar,
  Info,
  ChevronRight,
  Activity,
  BookOpen,
  Globe,
  Layers
} from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { NewsItem, AppSettings, TOPICS_LIST, ScheduleSettings } from './types';
import { fetchFiscalNews, sendToGoogleChat } from './services/geminiService';

const DEFAULT_SCHEDULE: ScheduleSettings = {
  enabled: false,
  startTime: "09:00",
  timesPerDay: 1,
  lastRun: null
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedWebhook = localStorage.getItem('google_chat_webhook') || '';
    const savedTopics = JSON.parse(localStorage.getItem('selected_topics') || '["SAT", "IMSS", "Infonavit"]');
    const savedSchedule = JSON.parse(localStorage.getItem('schedule_settings') || JSON.stringify(DEFAULT_SCHEDULE));
    return {
      googleChatWebhook: savedWebhook,
      selectedTopics: savedTopics,
      schedule: savedSchedule
    };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [results, setResults] = useState<NewsItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [nextExecution, setNextExecution] = useState<string | null>(null);

  const userTimeZone = useMemo(() => {
    try {
      return Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch (e) {
      return 'UTC';
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('google_chat_webhook', settings.googleChatWebhook);
    localStorage.setItem('selected_topics', JSON.stringify(settings.selectedTopics));
    localStorage.setItem('schedule_settings', JSON.stringify(settings.schedule));
  }, [settings]);

  const runAutomationTask = useCallback(async (isAuto = false) => {
    if (settings.selectedTopics.length === 0) {
      if (!isAuto) setError("Por favor selecciona al menos un tema.");
      return;
    }

    if (isAuto && !settings.googleChatWebhook) return;

    setIsLoading(true);
    setError(null);

    try {
      // SIEMPRE realiza una búsqueda fresca llamando a Gemini con Google Search
      const news = await fetchFiscalNews(settings.selectedTopics);
      setResults(news);

      if (isAuto && settings.googleChatWebhook && news.length > 0) {
        await sendToGoogleChat(settings.googleChatWebhook, news[0]);
        setSuccessMsg(`Automatización: Reporte actualizado y enviado.`);
        setTimeout(() => setSuccessMsg(null), 5000);
      }

      setSettings(prev => ({
        ...prev,
        schedule: { ...prev.schedule, lastRun: new Date().toISOString() }
      }));

    } catch (err: any) {
      const msg = err.message || "Error en la automatización.";
      if (!isAuto) setError(msg);
      console.error("Auto Error:", msg);
    } finally {
      setIsLoading(false);
    }
  }, [settings.selectedTopics, settings.googleChatWebhook]);

  useEffect(() => {
    const checkSchedule = () => {
      if (!settings.schedule.enabled) {
        setNextExecution(null);
        return;
      }

      const now = new Date();
      const [startH, startM] = settings.schedule.startTime.split(':').map(Number);
      const intervalHours = 24 / settings.schedule.timesPerDay;

      const slots: Date[] = [];
      for (let i = 0; i < settings.schedule.timesPerDay; i++) {
        const slot = new Date();
        slot.setHours(startH + (i * intervalHours), startM, 0, 0);
        slots.push(slot);
      }

      slots.sort((a, b) => a.getTime() - b.getTime());

      let targetSlot = slots.find(s => s > now);
      if (!targetSlot) {
        targetSlot = new Date(slots[0]);
        targetSlot.setDate(targetSlot.getDate() + 1);
      }

      setNextExecution(targetSlot.toLocaleTimeString('es-MX', { 
        hour: '2-digit', 
        minute: '2-digit',
        day: targetSlot.getDate() !== now.getDate() ? '2-digit' : undefined,
        month: targetSlot.getDate() !== now.getDate() ? 'short' : undefined
      }));

      const lastRunDate = settings.schedule.lastRun ? new Date(settings.schedule.lastRun) : null;
      const minsSinceLastRun = lastRunDate ? (now.getTime() - lastRunDate.getTime()) / (1000 * 60) : 999;

      const isSlotTime = slots.some(slot => {
        const diff = Math.abs(now.getTime() - slot.getTime()) / (1000 * 60);
        return diff < 1; 
      });

      if (isSlotTime && minsSinceLastRun > 10 && !isLoading) {
        runAutomationTask(true);
      }
    };

    const interval = setInterval(checkSchedule, 30000); 
    checkSchedule(); 

    return () => clearInterval(interval);
  }, [settings.schedule, isLoading, runAutomationTask]);

  const toggleTopic = (topic: string) => {
    setSettings(prev => ({
      ...prev,
      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  const updateSchedule = (key: keyof ScheduleSettings, value: any) => {
    setSettings(prev => ({
      ...prev,
      schedule: { ...prev.schedule, [key]: value }
    }));
  };

  return (
    <div className="min-h-screen pb-20 bg-slate-50/50">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-40 px-4 md:px-8 py-4 glass">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-600 p-2.5 rounded-xl shadow-lg shadow-emerald-100 transform -rotate-3 group hover:rotate-0 transition-transform cursor-pointer">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-800 tracking-tight leading-none mb-1">FiscalBot MX</h1>
              <div className="flex items-center gap-2">
                <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">IA en Tiempo Real</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden lg:flex items-center gap-6 px-6 py-2 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Zona Horaria</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                   <Globe size={12} className="text-indigo-500" /> {userTimeZone}
                </span>
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Estado</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                   <Activity size={12} className="text-emerald-500" /> Sistema Activo
                </span>
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col">
                <span className="text-[10px] text-slate-400 font-bold uppercase">Próximo Envío</span>
                <span className="text-xs font-bold text-emerald-600 flex items-center gap-1.5">
                   <Clock size={12} /> {nextExecution || 'Manual'}
                </span>
              </div>
            </div>

            <button 
              onClick={() => setShowSettings(true)}
              className="p-3 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all border border-transparent hover:border-emerald-100"
            >
              <SettingsIcon size={20} />
            </button>

            <button 
              onClick={() => runAutomationTask(false)}
              disabled={isLoading}
              className="bg-slate-900 hover:bg-black disabled:bg-slate-400 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 shadow-xl shadow-slate-200 transition-all active:scale-95"
            >
              {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={18} className="fill-current" />}
              <span className="hidden sm:inline">Buscar Ahora</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 md:p-8 space-y-8">
        {/* Alerts */}
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-red-500 p-2 rounded-lg text-white">
               <AlertCircle size={20} />
            </div>
            <p className="text-red-700 text-sm font-bold">{error}</p>
            <button onClick={() => setError(null)} className="ml-auto text-red-300 hover:text-red-500 text-xl">&times;</button>
          </div>
        )}
        {successMsg && (
          <div className="bg-emerald-50 border-l-4 border-emerald-500 p-5 rounded-2xl flex items-center gap-4 shadow-sm animate-in slide-in-from-top-4 duration-300">
            <div className="bg-emerald-500 p-2 rounded-lg text-white">
               <CheckCircle2 size={20} />
            </div>
            <p className="text-emerald-700 text-sm font-bold">{successMsg}</p>
            <button onClick={() => setSuccessMsg(null)} className="ml-auto text-emerald-300 hover:text-emerald-500 text-xl">&times;</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Left Column: Config */}
          <aside className="lg:col-span-4 space-y-6">
            <section className="bg-emerald-600 p-8 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden group">
              <div className="absolute -right-10 -bottom-10 text-white/10 group-hover:scale-110 transition-transform duration-700">
                <Clock size={200} />
              </div>

              <div className="relative z-10">
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-3">
                    <div className="bg-white/20 p-2 rounded-lg">
                      <Bell size={20} className="text-white" />
                    </div>
                    <h2 className="text-xl font-black">Autoprogramar</h2>
                  </div>
                  <button 
                    onClick={() => updateSchedule('enabled', !settings.schedule.enabled)}
                    className={`w-12 h-6 rounded-full transition-colors relative flex items-center ${settings.schedule.enabled ? 'bg-white' : 'bg-emerald-800'}`}
                  >
                    <div className={`absolute w-5 h-5 rounded-full transition-all shadow-md ${settings.schedule.enabled ? 'left-6 bg-emerald-600' : 'left-1 bg-white'}`} />
                  </button>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center gap-2 text-[10px] font-black text-emerald-100 uppercase tracking-widest bg-emerald-700/50 w-fit px-3 py-1 rounded-full border border-emerald-400/20">
                    <Globe size={12} /> Zona: {userTimeZone}
                  </div>

                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Primera actualización (Hora Local)</label>
                    <div className="relative">
                      <input 
                        type="time" 
                        value={settings.schedule.startTime}
                        onChange={(e) => updateSchedule('startTime', e.target.value)}
                        className="bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm w-full focus:ring-2 focus:ring-white outline-none font-bold text-white transition-all"
                      />
                      <Clock className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40" size={16} />
                    </div>
                  </div>

                  {/* INDICADOR DE TEMAS ACTIVOS PARA AUTOMATIZACION */}
                  {settings.schedule.enabled && (
                    <div className="p-4 bg-emerald-700/40 rounded-2xl border border-emerald-400/30">
                      <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-3 flex items-center gap-2">
                        <Layers size={12} /> Temas Activos para Envío
                      </label>
                      <div className="flex flex-wrap gap-1.5">
                        {settings.selectedTopics.length > 0 ? settings.selectedTopics.map(t => (
                          <span key={t} className="bg-white/10 px-2.5 py-1 rounded-lg text-[10px] font-black border border-white/10">
                            {t}
                          </span>
                        )) : (
                          <span className="text-[10px] text-emerald-200 font-bold">Sin temas seleccionados</span>
                        )}
                      </div>
                    </div>
                  )}

                  <div>
                    <label className="text-[10px] font-black text-white/60 uppercase tracking-widest block mb-2">Frecuencia de envío</label>
                    <div className="grid grid-cols-2 gap-2">
                      {[1, 2, 3, 4, 6, 12].map(num => (
                        <button
                          key={num}
                          onClick={() => updateSchedule('timesPerDay', num)}
                          className={`px-3 py-2.5 rounded-xl text-xs font-black border transition-all ${
                            settings.schedule.timesPerDay === num 
                            ? 'bg-white text-emerald-700 border-white' 
                            : 'bg-white/5 border-white/10 hover:bg-white/10'
                          }`}
                        >
                          {num} {num === 1 ? 'Vez' : 'Veces'} / día
                        </button>
                      ))}
                    </div>
                  </div>

                  {settings.schedule.enabled && (
                    <div className="pt-2 animate-in fade-in zoom-in-95">
                      <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 border border-white/10 flex items-center gap-4">
                        <div className="bg-emerald-400 p-2 rounded-lg text-emerald-900 shadow-inner">
                          <Calendar size={18} />
                        </div>
                        <div>
                          <p className="text-[10px] font-bold text-white/60 uppercase leading-none mb-1">Próxima Alerta</p>
                          <p className="text-sm font-black text-white leading-none">{nextExecution}</p>
                        </div>
                        <ChevronRight className="ml-auto text-white/30" size={18} />
                      </div>
                    </div>
                  )}

                  <div className="flex gap-3 p-4 bg-emerald-700/50 rounded-2xl border border-emerald-400/20">
                    <Info size={16} className="shrink-0 text-emerald-300 mt-0.5" />
                    <p className="text-[10px] text-emerald-100/80 leading-relaxed font-medium">
                      El sistema realizará una <strong>búsqueda en tiempo real</strong> de los temas seleccionados justo antes de enviarlos.
                    </p>
                  </div>
                </div>
              </div>
            </section>

            <section className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
              <div className="flex items-center gap-3 mb-6 text-slate-800 font-black">
                <div className="bg-slate-50 p-2 rounded-lg">
                  <Filter size={20} className="text-emerald-600" />
                </div>
                <h2>Temas a Monitorizar</h2>
              </div>
              <p className="text-[10px] text-slate-400 font-bold uppercase mb-4 tracking-widest">Afecta también al envío automático</p>
              <div className="grid grid-cols-2 gap-2">
                {TOPICS_LIST.map(topic => (
                  <button
                    key={topic}
                    onClick={() => toggleTopic(topic)}
                    className={`px-4 py-3 rounded-xl text-xs font-black transition-all border ${
                      settings.selectedTopics.includes(topic)
                        ? 'bg-slate-900 text-white border-slate-900 shadow-lg shadow-slate-200'
                        : 'bg-slate-50 text-slate-500 border-slate-100 hover:bg-slate-100'
                    }`}
                  >
                    {topic}
                  </button>
                ))}
              </div>
            </section>
          </aside>

          {/* Right Column: Feed */}
          <div className="lg:col-span-8 space-y-6">
            {isLoading && results.length === 0 ? (
              <div className="space-y-6">
                {[1, 2].map(i => (
                  <div key={i} className="bg-white p-10 rounded-[2.5rem] border border-slate-100 animate-pulse">
                    <div className="h-4 bg-slate-100 rounded w-24 mb-6"></div>
                    <div className="h-8 bg-slate-200 rounded w-3/4 mb-4"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-full mb-2"></div>
                    <div className="h-4 bg-slate-100 rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : results.length > 0 ? (
              results.map(item => (
                <article key={item.id} className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden group hover:shadow-2xl hover:-translate-y-1 transition-all duration-500">
                  <div className="p-10">
                    <div className="flex flex-wrap justify-between items-start gap-4 mb-8">
                      <div className="flex gap-2">
                        <span className="bg-emerald-50 text-emerald-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-100">
                          {item.topic}
                        </span>
                        {settings.schedule.enabled && (
                          <span className="bg-indigo-50 text-indigo-700 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100 flex items-center gap-2">
                            <Activity size={12} className="animate-pulse" /> Autopilot
                          </span>
                        )}
                      </div>
                      <span className="text-slate-400 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                        <Calendar size={14} className="text-slate-300" />
                        {item.date}
                      </span>
                    </div>

                    <div className="prose prose-slate max-w-none text-slate-600 mb-10 prose-headings:font-black prose-headings:text-slate-900 prose-strong:text-emerald-700 prose-li:marker:text-emerald-400">
                      <ReactMarkdown remarkPlugins={[remarkGfm]}>
                        {item.fullText}
                      </ReactMarkdown>
                    </div>

                    {item.links.length > 0 && (
                      <div className="border-t border-slate-100 pt-10">
                        <div className="flex items-center gap-3 mb-6">
                           <div className="bg-slate-100 p-2 rounded-lg text-slate-500">
                              <BookOpen size={16} />
                           </div>
                           <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Fuentes de Información y Lectura</h4>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {item.links.map((link, idx) => (
                            <a 
                              key={idx}
                              href={link.uri}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center justify-between gap-4 p-4 rounded-2xl bg-slate-50 border border-slate-100 hover:bg-emerald-50 hover:border-emerald-200 transition-all group/link shadow-sm hover:shadow-md"
                            >
                              <div className="flex items-center gap-3 overflow-hidden">
                                <div className="bg-white p-2.5 rounded-xl text-emerald-600 shadow-sm border border-slate-100 group-hover/link:border-emerald-200">
                                   <ExternalLink size={14} />
                                </div>
                                <span className="truncate font-bold text-sm text-slate-700 group-hover/link:text-emerald-800">{link.title}</span>
                              </div>
                              <ChevronRight size={16} className="shrink-0 text-slate-300 group-hover/link:translate-x-1 group-hover/link:text-emerald-500 transition-all" />
                            </a>
                          ))}
                        </div>
                        <p className="mt-6 text-[10px] text-slate-400 italic text-center font-medium">Haz clic en cualquier fuente para leer la noticia completa en el portal oficial.</p>
                      </div>
                    )}
                  </div>

                  <div className="bg-slate-50/50 px-10 py-6 flex flex-wrap justify-between items-center gap-4 border-t border-slate-100">
                    <button 
                      onClick={() => setResults([])}
                      className="text-slate-400 hover:text-red-500 text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-colors"
                    >
                      <Trash2 size={16} />
                      Borrar reporte
                    </button>
                    <button 
                      onClick={() => {
                        if (!settings.googleChatWebhook) {
                          setShowSettings(true);
                          setError("Configura el Webhook en ajustes.");
                        } else {
                          sendToGoogleChat(settings.googleChatWebhook, item)
                            .then(() => {
                              setSuccessMsg("¡Reporte con fuentes enviado con éxito!");
                              setTimeout(() => setSuccessMsg(null), 3000);
                            })
                            .catch(() => setError("No se pudo enviar. Revisa el webhook."));
                        }
                      }}
                      disabled={isLoading}
                      className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 shadow-xl shadow-emerald-200 transition-all active:scale-95 disabled:opacity-50"
                    >
                      <Send size={16} />
                      Enviar a Google Chat
                    </button>
                  </div>
                </article>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-32 text-center bg-white rounded-[3rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-emerald-500 via-indigo-500 to-emerald-500 bg-[length:200%_100%] animate-[gradient_3s_linear_infinite]"></div>
                <div className="bg-slate-50 p-10 rounded-full mb-8 transform group-hover:scale-110 transition-transform duration-500">
                  <Search className="text-slate-200" size={80} />
                </div>
                <h2 className="text-3xl font-black text-slate-800 mb-4 tracking-tight">Monitor Fiscal Inteligente</h2>
                <p className="text-slate-400 max-w-sm mb-10 leading-relaxed font-medium">
                  Configura tu automatización o realiza una búsqueda manual para recibir resúmenes de <span className="text-emerald-600 font-black">SAT, IMSS e Infonavit</span>.
                </p>
                <button 
                  onClick={() => runAutomationTask(false)}
                  className="bg-slate-900 hover:bg-black text-white px-10 py-4 rounded-2xl font-black shadow-2xl shadow-slate-200 transition-all active:scale-95"
                >
                  Iniciar Búsqueda
                </button>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-lg animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-500">
            <div className="p-12 border-b border-slate-50">
              <div className="flex justify-between items-center mb-12">
                <div>
                  <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Conexiones</h2>
                  <p className="text-slate-500 text-sm mt-2 font-medium">Vincula tu espacio de Google Chat para la automatización.</p>
                </div>
                <button 
                  onClick={() => setShowSettings(false)} 
                  className="text-slate-300 hover:text-slate-900 text-4xl font-light transition-colors"
                >
                  &times;
                </button>
              </div>

              <div className="space-y-10">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-4 uppercase tracking-[0.2em]">Webhook de Google Chat</label>
                  <div className="relative group">
                    <input 
                      type="text" 
                      value={settings.googleChatWebhook}
                      onChange={(e) => setSettings(prev => ({ ...prev, googleChatWebhook: e.target.value }))}
                      placeholder="https://chat.googleapis.com/v1/spaces/..."
                      className="w-full px-6 py-5 rounded-[1.5rem] border-2 border-slate-100 focus:border-emerald-500 focus:ring-4 focus:ring-emerald-50 outline-none transition-all pr-14 font-mono text-xs"
                    />
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-200 group-focus-within:text-emerald-500 transition-colors">
                      <Zap size={24} className="fill-current" />
                    </div>
                  </div>

                  <div className="mt-8 flex gap-5 p-6 bg-indigo-50 rounded-[2rem] border border-indigo-100 relative overflow-hidden">
                    <div className="absolute -right-4 -bottom-4 text-indigo-500/5">
                      <Info size={100} />
                    </div>
                    <Info size={24} className="text-indigo-600 shrink-0 mt-1" />
                    <div className="text-xs text-indigo-800 space-y-3 relative z-10">
