const DEFAULT_SCHEDULE: ScheduleSettings = {
  enabled: false,
  startTime: "08:30",
  timesPerDay: 1,
  lastRun: null
};

const getFriendlyDomainName = (url: string): string => {
  try {
    const urlObj = new URL(url);
    const hostname = urlObj.hostname;
    let clean = hostname
      .replace('www.', '')
      .replace(/\.(com|org|mx|gob|edu|net)$/g, '')
      .replace(/\.(com|org|mx|gob|edu|net)$/g, ''); 

    clean = clean.replace(/\./g, ' ');

    return clean.split(' ').map(word => {
      if (word.length <= 4) return word.toUpperCase();
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    }).join(' ');
  } catch {
    return "Fuente Oficial";
  }
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(() => {
    const savedWebhook = localStorage.getItem('google_chat_webhook') || '';
    const savedTopics = JSON.parse(localStorage.getItem('selected_topics') || '["SAT", "IMSS", "Infonavit"]');
    const savedSchedule = JSON.parse(localStorage.getItem('schedule_settings') || JSON.stringify(DEFAULT_SCHEDULE));
    return {
      googleChatWebhook: savedWebhook,
      selectedTopics: savedTopics,
      schedule: savedSchedule
    };
  });

  const [isLoading, setIsLoading] = useState(false);
  const [loadingStep, setLoadingStep] = useState("");
  const [results, setResults] = useState<NewsItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);
  const [nextExecution, setNextExecution] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('google_chat_webhook', settings.googleChatWebhook);
    localStorage.setItem('selected_topics', JSON.stringify(settings.selectedTopics));
    localStorage.setItem('schedule_settings', JSON.stringify(settings.schedule));
  }, [settings]);

  const runAutomationTask = useCallback(async (isAuto = false) => {
    if (settings.selectedTopics.length === 0) {
      if (!isAuto) setError("Selecciona al menos un tema para buscar.");
      return;
    }

    setIsLoading(true);
    setLoadingStep("Conectando con fuentes oficiales...");
    setError(null);

    try {
      setTimeout(() => setLoadingStep("Analizando cambios del día..."), 2000);
      const news = await fetchFiscalNews(settings.selectedTopics);
      setResults(news);

      if (isAuto && settings.googleChatWebhook && news.length > 0) {
        setLoadingStep("Enviando reporte a Google Chat...");
        await sendToGoogleChat(settings.googleChatWebhook, news[0]);
        setSuccessMsg(`Automatización completada: Noticias enviadas.`);
        setTimeout(() => setSuccessMsg(null), 5000);
      }

      setSettings(prev => ({
        ...prev,
        schedule: { ...prev.schedule, lastRun: new Date().toISOString() }
      }));

    } catch (err: any) {
      const msg = err.message || "Error al sincronizar noticias.";
      if (!isAuto) setError(msg);
    } finally {
      setIsLoading(false);
      setLoadingStep("");
    }
  }, [settings.selectedTopics, settings.googleChatWebhook]);

  // Manejo de la lógica de programación (Schedule)
  useEffect(() => {
    const checkSchedule = () => {
      if (!settings.schedule.enabled) {
        setNextExecution(null);
        return;
      }

      const now = new Date();
      const [startH, startM] = settings.schedule.startTime.split(':').map(Number);
      const intervalHours = 24 / settings.schedule.timesPerDay;

      const slots: Date[] = [];
      for (let i = 0; i < settings.schedule.timesPerDay; i++) {
        const slot = new Date();
        slot.setHours(startH + (i * intervalHours), startM, 0, 0);
        slots.push(slot);
      }

      slots.sort((a, b) => a.getTime() - b.getTime());

      let targetSlot = slots.find(s => s > now);
      if (!targetSlot) {
        targetSlot = new Date(slots[0]);
        targetSlot.setDate(targetSlot.getDate() + 1);
      }

      setNextExecution(targetSlot.toLocaleTimeString('es-MX', { 
        hour: '2-digit', 
        minute: '2-digit',
        day: targetSlot.getDate() !== now.getDate() ? '2-digit' : undefined,
      }));

      const lastRunDate = settings.schedule.lastRun ? new Date(settings.schedule.lastRun) : null;
      const minsSinceLastRun = lastRunDate ? (now.getTime() - lastRunDate.getTime()) / (1000 * 60) : 999;

      const isSlotTime = slots.some(slot => {
        const diff = Math.abs(now.getTime() - slot.getTime()) / (1000 * 60);
        return diff < 1; 
      });

      if (isSlotTime && minsSinceLastRun > 10 && !isLoading) {
        runAutomationTask(true);
      }
    };

    const interval = setInterval(checkSchedule, 30000);
    checkSchedule();
    return () => clearInterval(interval);
  }, [settings.schedule, isLoading, runAutomationTask]);

  const toggleTopic = (topic: string) => {
    setSettings(prev => ({
      ...prev,
      selectedTopics: prev.selectedTopics.includes(topic)
        ? prev.selectedTopics.filter(t => t !== topic)
        : [...prev.selectedTopics, topic]
    }));
  };

  return (
    <div className="min-h-screen pb-20 bg-[#F8FAFC]">
      {/* Header Premium */}
      <header className="bg-white/80 border-b border-slate-200 sticky top-0 z-40 px-6 py-4 backdrop-blur-md">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="bg-emerald-600 p-2.5 rounded-xl shadow-lg shadow-emerald-200">
              <Newspaper className="text-white" size={24} />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-900 tracking-tight">FiscalBot MX</h1>
              <div className="flex items-center gap-2">
                <div className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></div>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Monitoreo 24/7 • Fuentes Confiables</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden md:flex items-center gap-4 mr-4 px-4 py-2 bg-slate-50 rounded-xl border border-slate-100">
              <div className="flex flex-col items-end">
                <span className="text-[9px] text-slate-400 font-bold uppercase">Estado del Sistema</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1">
                   <ShieldCheck size={12} className="text-emerald-500" /> Sincronizado
                </span>
              </div>
            </div>

            <button 
              onClick={() => setShowSettings(true)}
              className="p-3 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all"
            >
              <SettingsIcon size={20} />
            </button>

            <button 
              onClick={() => runAutomationTask(false)}
              disabled={isLoading}
              className="bg-slate-900 hover:bg-black disabled:bg-slate-300 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-xl shadow-slate-200 transition-all active:scale-95"
            >
              {isLoading ? <Loader2 className="animate-spin" size={18} /> : <RefreshCcw size={18} />}
              <span className="hidden sm:inline">{isLoading ? "Buscando..." : "Buscar Noticias Hoy"}</span>
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-6 md:p-10 space-y-8">
        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
            <AlertCircle className="text-red-500" size={20} />
            <p className="text-red-800 text-sm font-medium">{error}</p>
          </div>
