import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Topic, NewsItem } from "../types";

const API_KEY = process.env.API_KEY || '';

export const fetchFiscalNews = async (topics: string[]): Promise<NewsItem[]> => {
  if (!API_KEY) {
    throw new Error("API Key no configurada.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = 'gemini-3-flash-preview';

  const today = new Date().toLocaleDateString('es-MX', { 
    day: '2-digit', 
    month: 'long', 
    year: 'numeric' 
  });

  const topicsStr = topics.join(', ');

  const prompt = `
    Eres un analista de inteligencia fiscal especializado en el marco legal mexicano.
    FECHA ACTUAL: ${today}.

    INSTRUCCIONES DE BÚSQUEDA:
    Utiliza Google Search para encontrar noticias publicadas ESPECÍFICAMENTE HOY o en las últimas 24 horas sobre: ${topicsStr}.

    FUENTES PRIORITARIAS:
    1. Diario Oficial de la Federación (dof.gob.mx) - busca decretos o acuerdos del día.
    2. SAT (sat.gob.mx) - busca nuevos comunicados o reglas de la RMF.
    3. IMSS / Infonavit - busca acuerdos del consejo técnico o avisos de recaudación.
    4. Medios especializados: El Economista (sección Valle de México/Fiscal), IDC Online, Fiscalia.

    ESTRUCTURA DEL REPORTE:
    - ### [Título de la Noticia]
    - **Resumen Ejecutivo:** Explica qué cambió y a quién afecta.
    - **Vigencia:** Indica si entra en vigor hoy, mañana o en una fecha específica.
    - **Acción Sugerida:** Qué debe hacer el contador o la empresa hoy.

    NOTAS IMPORTANTES:
    - Si no hay noticias relevantes publicadas hoy, resume la noticia más importante de la semana actual.
    - DEBES incluir una sección final de "Fuentes Consultadas" con URLs directas.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "No se detectaron cambios fiscales críticos en las últimas 24 horas.";

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    let links = chunks
      .filter(chunk => chunk.web)
      .map(chunk => ({
        title: chunk.web?.title || 'Fuente oficial',
        uri: chunk.web?.uri || ''
      }));

    const urlRegex = /(https?:\/\/[^\s)\]]+)/g;
    const matches = text.match(urlRegex);
    if (matches) {
      matches.forEach(url => {
        const cleanUrl = url.replace(/[.,;]$/, '');
        if (!links.some(l => l.uri === cleanUrl)) {
          links.push({ title: 'Enlace detectado', uri: cleanUrl });
        }
      });
    }

    links = links
      .filter(link => link.uri && link.uri.startsWith('http'))
      .filter((link, index, self) => 
        index === self.findIndex((t) => t.uri === link.uri)
      );

    return [{
      id: crypto.randomUUID(),
      topic: topics.length > 1 ? "Resumen Diario" : topics[0],
      title: `Boletín Fiscal Diario: ${today}`,
      summary: text.substring(0, 200) + "...",
      fullText: text,
      date: today,
      links: links.slice(0, 8)
    }];

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("Error al consultar las fuentes de noticias.");
  }
};

const formatForGoogleChat = (text: string): string => {
  return text
    .replace(/^### (.*?)$/gm, '*$1*') 
    .replace(/\*\*(.*?)\*\*/g, '*$1*') 
    .replace(/^- /gm, '• '); 
};

export const sendToGoogleChat = async (webhookUrl: string, newsItem: NewsItem) => {
  if (!webhookUrl) throw new Error("Webhook URL no configurada.");

  const formattedBody = formatForGoogleChat(newsItem.fullText);

  let linksSection = "";
  if (newsItem.links.length > 0) {
    linksSection = `\n\n*🔗 FUENTES DE HOY:*\n`;
    linksSection += newsItem.links
      .map(l => `• ${l.title}: ${l.uri}`)
      .join('\n');
  }

  const message = {
    text: `🗞️ *${newsItem.title}*\n\n${formattedBody}${linksSection}\n\n_Enviado vía FiscalBot MX_`
  };

  const response = await fetch(webhookUrl, {
    method: 'POST',
    mode: 'no-cors',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(message)
  });

  return { success: true };
};

