      ...prev,
      schedule: { ...prev.schedule, [key]: value }
    }));
  };

  return (
    <div className="min-h-screen pb-20 bg-[#F8FAFC]">
      <header className="bg-white/80 border-b border-slate-200 sticky top-0 z-40 px-6 py-4 backdrop-blur-md">
