                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Monitoreo Diario (2025)</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden lg:flex items-center gap-6 px-4 py-2 bg-slate-50 rounded-xl border border-slate-100">
              <div className="flex flex-col items-end">
                <span className="text-[9px] text-slate-400 font-bold uppercase">Estado</span>
                <span className="text-xs font-bold text-slate-700 flex items-center gap-1">
                   <ShieldCheck size={12} className="text-emerald-500" /> Activo
                </span>
              </div>
              <div className="w-px h-6 bg-slate-200"></div>
              <div className="flex flex-col items-end">
                <span className="text-[9px] text-slate-400 font-bold uppercase">Próximo Envío</span>
                <span className="text-xs font-bold text-emerald-600">
                   {nextExecution || 'Manual'}
