                                  <ExternalLink size={14} />
                                </div>
                                <span className="text-sm font-bold truncate">
                                  {link.title !== 'Enlace detectado' && link.title !== 'Fuente oficial' ? link.title : getFriendlyDomainName(link.uri)}
