                  <div className="bg-slate-50/50 px-10 py-6 flex flex-wrap justify-between items-center gap-4 border-t border-slate-100">
                    <button onClick={() => setResults([])} className="text-slate-400 hover:text-red-500 text-xs font-bold flex items-center gap-2 transition-colors">
                      <Trash2 size={16} /> Limpiar
