                          sendToGoogleChat(settings.googleChatWebhook, item)
                            .then(() => {
                              setSuccessMsg("¡Reporte enviado!");
                              setTimeout(() => setSuccessMsg(null), 3000);
                            })
                            .catch(() => setError("Error al enviar."));
                        }
                      }}
                      className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3.5 rounded-xl font-bold text-sm flex items-center gap-2 transition-all active:scale-95 shadow-lg shadow-emerald-100"
                    >
                      <Send size={16} /> Enviar a Google Chat
                    </button>
