import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Topic, NewsItem } from "../types";

const API_KEY = process.env.API_KEY || '';

export const fetchFiscalNews = async (topics: string[]): Promise<NewsItem[]> => {
  if (!API_KEY) {
    throw new Error("API Key no configurada.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = 'gemini-3-flash-preview';

  const today = new Date().toLocaleDateString('es-MX', { 
    day: '2-digit', 
    month: 'long', 
    year: 'numeric' 
  });

  const topicsStr = topics.join(', ');

  // Prompt mejorado para priorización inteligente
  const prompt = `
    Eres un analista de inteligencia fiscal de alto nivel en México. 
    Hoy es ${today}. Tu tarea es buscar y resumir noticias sobre: ${topicsStr}.

    REGLAS DE PRIORIZACIÓN (Orden de importancia):
    1. CRÍTICO: Publicaciones en el Diario Oficial de la Federación (DOF), cambios en leyes o decretos presidenciales.
    2. URGENTE: Nuevos plazos, prórrogas o fechas límite de SAT, IMSS o Infonavit.
    3. RELEVANTE: Cambios en valores (UMA, Salario Mínimo, Tasas), nuevos formatos de CFDI o reglas de la RMF.
    4. INFORMATIVO: Comunicados de prensa generales o análisis de expertos.

    ESTRUCTURA DEL REPORTE:
    - # 🚨 ALERTAS DE ALTO IMPACTO (Solo si hay cambios legales o plazos hoy)
    - ## Resumen por Tema
      (Agrupa la información por tema de forma clara)
    - ## Acciones Recomendadas
      (Qué debe hacer el despacho o empresa ante estas noticias)

    FUENTES OBLIGATORIAS: dof.gob.mx, sat.gob.mx, imss.gob.mx, infonavit.org.mx.

    REGLAS DE FORMATO:
    - Usa Markdown.
    - Usa **negritas** para fechas y cifras.
    - Si un tema NO tiene noticias relevantes hoy, no lo menciones o indica brevemente "Sin cambios relevantes".
    - Incluye la sección final "Fuentes Consultadas" con URLs directas.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "No se detectaron cambios críticos para los temas seleccionados hoy.";

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    let links = chunks
      .filter(chunk => chunk.web)
      .map(chunk => ({
        title: chunk.web?.title || 'Fuente oficial',
        uri: chunk.web?.uri || ''
      }));

    const urlRegex = /(https?:\/\/[^\s)\]]+)/g;
    const matches = text.match(urlRegex);
    if (matches) {
      matches.forEach(url => {
        const cleanUrl = url.replace(/[.,;]$/, '');
        if (!links.some(l => l.uri === cleanUrl)) {
          links.push({ title: 'Enlace directo', uri: cleanUrl });
        }
      });
    }

    links = links
      .filter(link => link.uri && link.uri.startsWith('http'))
      .filter((link, index, self) => 
        index === self.findIndex((t) => t.uri === link.uri)
      );

    return [{
      id: crypto.randomUUID(),
      topic: topics.length > 3 ? "Resumen Multitemático" : topics.join(', '),
      title: `Inteligencia Fiscal Diaria: ${today}`,
      summary: text.substring(0, 300) + "...",
      fullText: text,
      date: today,
      links: links.slice(0, 10)
    }];

  } catch (error) {
    console.error("Error fetching news:", error);
    throw error;
  }
};

const formatForGoogleChat = (text: string): string => {
  return text
    .replace(/^# (.*?)$/gm, '🚨 *RELEVANCIA MÁXIMA: $1*')
    .replace(/^## (.*?)$/gm, '*$1*')
    .replace(/\*\*(.*?)\*\*/g, '*$1*')
    .replace(/^- /gm, '• ');
};

export const sendToGoogleChat = async (webhookUrl: string, newsItem: NewsItem) => {
  if (!webhookUrl) throw new Error("Webhook URL no configurada.");

  const formattedBody = formatForGoogleChat(newsItem.fullText);

  let linksSection = "";
  if (newsItem.links.length > 0) {
    linksSection = `\n\n----------------------------------\n*📖 FUENTES OFICIALES:*\n\n`;
    linksSection += newsItem.links
      .map(l => `• *${l.title.trim()}*\n${l.uri}`)
      .join('\n\n');
  }

  const message = {
    text: `🔔 *${newsItem.title.toUpperCase()}*\n\n${formattedBody}${linksSection}\n\n_Priorizado por impacto legal • FiscalBot MX_`
  };

  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(message)
  });

  if (!response.ok) {
    throw new Error(`Error al enviar: ${response.statusText}`);
  }

  return await response.json();
};

